	"context"
	"encoding/json"
	"fmt"
	"sort"
	"sync"
	"time"

	node "github.com/jepsen-io/maelstrom/demo/go"
)

// MsgCount is the count message type
type MsgCount struct {
	MsgID   int64
	Visitors int
}

// MsgCounted is the response to a count message
type MsgCounted struct {
	InReplyTo int64
}

// MsgTotal is the total request message type
type MsgTotal struct {
	MsgID int64
}

// MsgTotalIs is the response to a total message
type MsgTotalIs struct {
	InReplyTo    int64
	VisitorsSoFar int
}

// NodeState tracks local state for this node
type NodeState struct {
	id            string
	nodes         []string
	localCount    int64  // current count at this turnstile
	inflightCounts map[int64]int // counts that we've received but not yet acknowledged
	countWaitMu   sync.Mutex
}

var (
	seqKV node.SeqKVClient = nil
	kvKey     string
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	ns := &NodeState{
		localCount:         0,
		inflightCounts:     make(map[int64]int),
	}

	// Get node info from maelstrom
	info, err := node.Handle(ctx, ctx, []byte(`{"type": "init"}`))
	if err != nil {
		fmt.Fprintf(stderr, "failed to handle init: %v\n", err)
	}

	var nids []string
	for _, b := range info.Bytes() {
		var m map[string]interface{}
		json.Unmarshal(b, &m)
		if id, ok := m["id"].(string); ok {
			nids = append(nids, id)
		}
	}
	sort.Strings(nids)
	ns.id = nids[0]
	ns.nodes = nids

	seqKV = node.NewSeqKV(ctx, "seq-kv")
	kvKey = fmt.Sprintf("g-counter-%s", ns.id)

	for {
		select {
		case msg := <-ctx.Done():
			return
		default:
		}

		b, err := io.ReadFull(br) // read input message
		if err != nil || len(b) == 0 {
			break
		}

		var m map[string]interface{}
		json.Unmarshal(b, &m)
		mtype, _ := m["type"].(string)

		switch mtype {
		case "count":
			handleCount(ctx, ns, b)
		case "total":
			handleTotal(ctx, ns)
		default:
			fmt.Fprintf(stderr, "unknown message type: %v\n", mtype)
		}
	}

	seqKV.Close()
}

func handleCount(ctx context.Context, ns *NodeState, b []byte) {
	var req MsgCount
	json.Unmarshal(b, &req)

	// Add to local count and store in KV store
	ns.localCount += int64(req.Visitors)

	// Write to KV store for consistency across nodes
	val := fmt.Sprintf("%d", ns.localCount)
	seqKV.Write(ctx, kvKey, []byte(val))

	// Reply immediately with what we've seen locally
	reply := MsgCounted{InReplyTo: req.MsgID}
	replyJSON, _ := json.Marshal(reply)
	fmt.Fprintln(stdout, string(replyJSON))
}

func handleTotal(ctx context.Context, ns *NodeState) {
	var req MsgTotal
	json.Unmarshal(b, &req)

	// Read the total from KV store (should have all 4 turnstiles' data)
	valBytes := seqKV.Read(ctx, kvKey)
	total := int64(0)
	if valBytes != nil {
		fmt.Sscanf(string(valBytes), "%d", &total)
	}

	reply := MsgTotalIs{
		InReplyTo:      req.MsgID,
		VisitorsSoFar:  int(total),
	}
	replyJSON, _ := json.Marshal(reply)
	fmt.Fprintln(stdout, string(replyJSON))
}

